#' Bootstrap Confidence Intervals for Dispersion Estimates
#'
#' Calculate sample-level two-sided bootstrap confidence
#' intervals for time-averaging statistics. Accepts object of the
#' class 'postdist' generated by function \code{\link{postdist}}
#'
#' @details Calculates accelerated-bias-corrected non-parametric bootstrap
#' confidence intervals for a sample of dated specimens using
#' functions \code{\link[boot]{boot}} and \code{\link[boot]{boot.ci}}
#' from package "boot". These include:
#'
#' ETA - bootstrap estimate of confidence intervals for
#' Estimated Time-Averaging  corrected for dating uncertainty.
#' calculated as 2 * square root of TAV-AEV (see Ritter et al. 2023)
#'
#' IQR - bootstrap estimate IQR corrected for dating uncertainty computed
#' as ETA/2 multiplied by iq.age/std.age (see Tomasovych et al. 2023)
#'
#' L2 - bootstrap estimate of L-dispersion calculated using
#' function \code{\link[lmom]{samlmu}} from package "lmom".
#' NOTE: L2 is not adjusted for dating uncertainty.
#'
#' L3 - bootstrap estimate of L-skewness calculated using
#' function \code{\link[lmom]{samlmu}} from package "lmom".
#'
#' @param x An object of the class 'postdist' returned by \code{\link{postdist}} function
#'
#' @param iter A numerical value (default=1000) defining the number of
#' replicate pseudo-samples that will be generated to derive bootstrap
#' estimates.
#'
#' @param conf A nuemrical value specifying confidence intervals
#' (default = 0.95)
#'
#' @return A data.frame with estimates of parameters and
#' sample-level bootstrap confidence limits. The following parameters
#' are currently available: ETA, ETA50, L2, L3. L-moments calculated
#' using function \code{\link[lmom]{samlmu}} from package "lmom".
#'
#' @examples
#'
#' out1 <- postdist(age=florida$post$cal.BP, prob=florida$post$probability,
#' id=florida$post$UniqueID, size=1000)
#'
#' out2 <- tastats.boot(out1, iter=100)
#' out2
#'
#' @importFrom boot boot boot.ci
#' @importFrom lmom samlmu
#' @importFrom stats var sd median IQR
#'
#' @export
#'
#' @references Angelo Canty and Brian Ripley (2024). boot:
#' Bootstrap R (S-Plus) Functions. R package version 1.3-31.
#'
#' Davison, A. C. & Hinkley, D. V. (1997) Bootstrap Methods and
#' Their Applications. Cambridge University Press, Cambridge.
#' ISBN 0-521-57391-2
#'
#' Hosking, JRM, 2023, L-Moments. R package, version 3.0.
#' https://CRAN.R-project.org/package=lmom
#'
#' Ritter, M, Erthal F, Kosnik, MA, Kowalewski, M, Coimbra, CJ,
#' Caron, F, Kaufman, DS, 2023, Onshore-offshore trends in the temporal
#' resolution of molluscan death assemblages: how age-frequency
#' distributions reveal Quaternary sea-level history.
#' Palaios, 38: 148-157. http://dx.doi.org/10.2110/palo.2021.041
#'
#' Tomašových, A., Kidwell, S.M. and Dai, R., (2023), A downcore increase
#' in time averaging is the null expectation from the transit of death assemblages
#' through a mixed layer. Paleobiology, 49(3), pp.527-562.
#' https://doi.org/10.1017/pab.2022.42
#'

tastats.boot <- function(x, iter=1000, conf=0.95) {
  if (!('postdist' %in% class(x))) stop('object of the class "postdist" is required')
  # ETA and ETA 50
  ETA.boot.F <- function(x, w)
    2*sqrt(var(as.vector(x[w,])) - mean(apply(x[w,], 1, var)))
  boot.out <- boot::boot(x, ETA.boot.F, R=iter)
  ci.out <- suppressWarnings(boot::boot.ci(boot.out, type='bca', conf=conf))
  corr.IQR <- stats::IQR(apply(x, 1, median))/sd(apply(x, 1, median))
  ci.out2 <- data.frame(ETA=ci.out$t0,
                       ETA.lower=ci.out$bca[4],
                       ETA.upper=ci.out$bca[5],
                       ETA50=0.5*ci.out$t0*corr.IQR,
                       ETA50.lower=0.5*ci.out$bca[4]*corr.IQR,
                       ETA50.upper=0.5*ci.out$bca[5]*corr.IQR)
  rownames(ci.out2) <- NULL
  # L2
  l2F <- function(x) as.numeric(lmom::samlmu(x)[2])
  L2.boot.F <- function(x, w) l2F(apply(x[w,], 1, median))
  boot.out1 <- boot::boot(x, L2.boot.F, R=iter)
  ci.out.L2 <- suppressWarnings(boot::boot.ci(boot.out1, type='bca',
                                              conf=conf))
  ci.out2.L2 <- data.frame(L2=ci.out.L2$t0,
                           L2.lower=ci.out.L2$bca[4],
                           L2.upper=ci.out.L2$bca[5])
  rownames(ci.out2.L2) <- NULL

  # L3
      l3F <- function(x) as.numeric(lmom::samlmu(x)[3])
      L3.boot.F <- function(x, w) l3F(apply(x[w,], 1, median))
      boot.out2 <- boot::boot(x, L3.boot.F, R=iter)
      ci.out.L3 <- suppressWarnings(boot::boot.ci(boot.out2, type='bca', conf=conf))
      ci.out2.L3 <- data.frame(L3=ci.out.L3$t0,
                            L3.lower=ci.out.L3$bca[4],
                            L3.upper=ci.out.L3$bca[5])
      rownames(ci.out2.L3) <- NULL
    return(cbind(ci.out2, ci.out2.L2, ci.out2.L3))
}
